"""Roman numeral conversion (1..3999)."""

# Value -> symbol pairs in descending order, including subtractive pairs.
_ROMAN_MAP = [
    (1000, 'M'),
    (900, 'CM'),
    (500, 'D'),
    (400, 'CD'),
    (100, 'C'),
    (90, 'XC'),
    (50, 'L'),
    (40, 'XL'),
    (10, 'X'),
    (9, 'IX'),
    (5, 'V'),
    (4, 'IV'),
    (1, 'I'),
]


def to_roman(n: int) -> str:
    """Convert an integer 1..3999 to its Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"Expected an integer, got {type(n).__name__}")
    if n < 1 or n > 3999:
        raise ValueError(f"Value must be between 1 and 3999, got {n}")

    parts = []
    for value, symbol in _ROMAN_MAP:
        while n >= value:
            parts.append(symbol)
            n -= value
    return ''.join(parts)


def from_roman(s: str) -> int:
    """Convert a Roman numeral string back to an integer."""
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__}")
    if not s:
        raise ValueError("Empty string is not a valid Roman numeral")

    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Validate that all characters are valid Roman numeral symbols
    for ch in s:
        if ch not in roman_values:
            raise ValueError(f"Invalid character '{ch}' in '{s}'")

    # Convert to list of values
    values = [roman_values[ch] for ch in s]

    # Compute the numeric value
    total = 0
    for i in range(len(values)):
        if i + 1 < len(values) and values[i] < values[i + 1]:
            total -= values[i]
        else:
            total += values[i]

    # Round-trip check: convert back to Roman and compare
    if to_roman(total) != s:
        raise ValueError(f"'{s}' is not a well-formed Roman numeral")

    return total
